# Let's look for strings in the binary that might give us hints
import re

target = "{TARGET}"
with open(target, 'rb') as f:
    data = f.read()

# Search for printable strings of length 4+
strings = []
current = b""
for i, byte in enumerate(data):
    if 32 <= byte < 127:
        current += bytes([byte])
    else:
        if len(current) >= 6:
            strings.append((i - len(current), current.decode('ascii', errors='replace')))
        current = b""

# Print interesting strings
print("Interesting strings found:")
for pos, s in strings:
    # Filter for meaningful strings
    if any(keyword in s.lower() for keyword in ['flag', 'pass', 'key', 'correct', 'wrong', 'valid', 'invalid', 'input', 'usage', 'func', 'wasm', 'module', 'arg']):
        print(f"  0x{pos:x}: {s}")

print("\n--- All strings that look like potential flags ---")
for pos, s in strings:
    # Look for flag-like patterns
    if re.match(r'^[A-Za-z0-9_{}]+$', s) and len(s) > 10:
        print(f"  0x{pos:x}: {s[:100]}")

# Let's look for cross-references to that hex string
import angr

target = "{TARGET}"
proj = angr.Project(target, auto_load_libs=False)

# The hex string is at 0x45ea3b
string_addr = 0x45ea3b

# Get the CFG
cfg = proj.analyses.CFGFast()

# Look for xrefs to this address
print(f"Looking for cross-references to 0x{string_addr:x}")

# Check if there are any references
xrefs = []
for func_addr, func in cfg.functions.items():
    try:
        for block in func.blocks:
            for ins in block.capstone.insns:
                # Check if the instruction references our address
                if string_addr in ins.op_str or hex(string_addr) in ins.op_str:
                    xrefs.append((ins.address, ins.mnemonic, ins.op_str))
                # Also check for relative addressing
                for op in ins.operands:
                    if hasattr(op, 'imm'):
                        if abs(op.imm - string_addr) < 0x1000:
                            xrefs.append((ins.address, ins.mnemonic, ins.op_str, op.imm))
    except Exception as e:
        pass

print(f"Found {len(xrefs)} references")
for xref in xrefs[:20]:
    print(f"  {xref}")

# Also let's look at the raw bytes around the string to understand context better
data = proj.loader.memory.load(string_addr - 32, 100)
print(f"\nContext around string:")
print(data)

